  "severity": "critical",
  "host_observations": [
    {"host": "ADFS-CORP-01.corp.local", "role": "production-idp", "user": "k.osman", "first_seen": "2033-03-08T22:08:08+0000", "last_seen": "2033-03-08T22:14:30+0000"}
